fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since both vectors have the same length, zip them and apply bitwise AND element-wise
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x & y)
     .collect()
}